using System.Text.Json;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Controls.Primitives;
using Avalonia.Interactivity;
using Avalonia.Media;
using Avalonia.Media.Imaging;
using Avalonia.VisualTree;
using LtcPlayer.App;
namespace LtcPlayer.Avalonia;
public static class PresentationVerification
{
 static void Check(bool value,string message){if(!value)throw new IOException(message);}
 static byte[] Center(byte[] data,int width,int height)=>data.Skip((height/2*width+width/2)*4).Take(4).ToArray();
 public static async Task RunAsync(MainWindow w,string folder){
  Directory.CreateDirectory(folder);var results=new List<object>();bool failed=false;int receiving=0,inputFrame=45;RenderSession? output=null;
  async Task Until(Func<bool> check){for(int i=0;i<1500;i++){if(check())return;await Task.Delay(10);}throw new TimeoutException(JsonSerializer.Serialize(new{Output=w.LatestObservation,Preview=w.PreviewObservation,State=w.Preview.Snapshot}));}
  async Task Test(string name,Func<Task> body){try{await body();results.Add(new{test=name,status="PASS"});}catch(Exception e){failed=true;results.Add(new{test=name,status="FAIL",detail=e.ToString()});}File.WriteAllText(Path.Combine(folder,"results.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}
  string file=Path.Combine(folder,"cover.png");using(var bitmap=new RenderTargetBitmap(new PixelSize(64,64),new Vector(96,96))){using(var dc=bitmap.CreateDrawingContext())dc.DrawRectangle(Brushes.Blue,null,new Rect(0,0,64,64));bitmap.Save(file);}
  var a=new CueRow{FilePath=Program.Option("--media")!};var b=new CueRow{FilePath=a.FilePath};b.SetStart("00:00:20:00");
  Button RowButton(CueRow cue,string cls)=>w.FindControl<DataGrid>("CueGrid")!.GetVisualDescendants().OfType<Button>().First(x=>ReferenceEquals(x.DataContext,cue)&&x.Classes.Contains(cls));
  void Play(CueRow cue)=>RowButton(cue,"cue-play").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
  try{
   await Test("fade reversal is continuous; zero duration cuts immediately",()=>{var fade=new CoverController();fade.Set(true,1,10);Check(Math.Abs(fade.Amount(10.5)-.5)<.001,"forward");fade.Set(false,2,10.5);Check(Math.Abs(fade.Amount(10.5)-.5)<.001&&Math.Abs(fade.Amount(11.5)-.25)<.001,"reversal");fade.Set(true,0,11.5);Check(fade.Amount(11.5)==1,"cut");return Task.CompletedTask;});
   await Test("image load and legacy defaults; invalid asset rejected",async()=>{var image=await CoverImageLoader.LoadAsync(file);Check(image is {Width:2048,Height:2048}||image is {Width:64,Height:64},"decoded dimensions");Check(image!.Pixels[0]==255&&image.Pixels[2]==0,"BGRA");string legacy=Path.Combine(folder,"legacy.json");File.WriteAllText(legacy,"{}");Check(InputSettings.Load(legacy) is {CoverPath:"",FadeSeconds:1},"legacy defaults");bool rejected=false;try{await CoverImageLoader.LoadAsync(file+".missing");}catch{rejected=true;}Check(rejected,"invalid image accepted");});
   await Test("GPU blend endpoints / midpoint / black fallback / no accumulation",async()=>{
    var display=VideoRenderer.Displays().First(d=>d.Primary!=0);using var renderer=new VideoRenderer(display,OutputPresentationMode.Compatibility);var red=new byte[display.Width*display.Height*4];for(int i=0;i<red.Length;i+=4){red[i+2]=red[i+3]=255;}renderer.Present(red);renderer.SetCover(await CoverImageLoader.LoadAsync(file));renderer.SetCoverMix(.5f);renderer.Redraw();var mid=Center(renderer.Readback(),display.Width,display.Height);Check(Math.Abs(mid[0]-128)<=1&&Math.Abs(mid[2]-128)<=1,"midpoint "+string.Join(',',mid));renderer.Redraw();Check(mid.SequenceEqual(Center(renderer.Readback(),display.Width,display.Height)),"cumulative blend");renderer.SetCoverMix(1);renderer.Redraw();Check(Center(renderer.Readback(),display.Width,display.Height)[0]==255,"cover endpoint");var full=renderer.Readback();Check(full[(display.Height/2*display.Width+1)*4]==0,"cover aspect padding");renderer.SetCover(null);renderer.Redraw();Check(Center(renderer.Readback(),display.Width,display.Height).Take(3).All(x=>x==0),"unregistered not black");renderer.SetCoverMix(0);renderer.Redraw();Check(Center(renderer.Readback(),display.Width,display.Height)[2]==255,"video endpoint");
   });
   await ShowProgramService.RefreshAsync(a,CancellationToken.None);await ShowProgramService.RefreshAsync(b,CancellationToken.None);
   await w.ApplySettingsAsync(new(new(Rate:"29.97 DF",OutputMode:OutputPresentationMode.Compatibility,CoverPath:file,FadeSeconds:.2),VideoRenderer.Displays().First(d=>d.Primary!=0)));
   await w.Monitor.ConfigureAsync(new(Rate:"29.97 DF"),async(clock,token)=>{while(!token.IsCancellationRequested){if(Volatile.Read(ref receiving)!=0){int f=Interlocked.Increment(ref inputFrame);clock.Accept(new TcFrame{Seconds=f/30,Frame=f%30,Drop=1},MasterClock.Timestamp());}await Task.Delay(33,token);}});
   w.Editor.Add(a);w.Editor.Add(b);await Task.Delay(200);output=w.Surface.Canvas;
   await Test("incoming LTC takes preview; no external output or audio",async()=>{Play(b);await Until(()=>w.Preview.Snapshot.State==PreviewState.Playing);Volatile.Write(ref receiving,1);await Until(()=>w.PreviewObservation is {FramePts:>0} t&&t.CueId==a.CueId);Check(!w.IsArmed&&!w.Surface.Canvas.OutputAttached&&PreviewAudio.ActiveStreams==0,"external output/audio started");await Until(()=>!RowButton(b,"cue-play").IsEnabled);});
   await Test("LTC loss holds exact preview; row play can take over",async()=>{Volatile.Write(ref receiving,0);await Until(()=>w.PreviewObservation?.State==SyncState.LOST);var held=w.PreviewObservation!.FramePts;await Task.Delay(220);Check(w.PreviewObservation.FramePts==held,"lost advanced");Play(b);await Until(()=>w.Preview.Snapshot.State==PreviewState.Playing&&w.PreviewObservation==null);});
   await Test("second LTC acquisition restores synchronization automatically",async()=>{Volatile.Write(ref receiving,1);await Until(()=>w.PreviewObservation is {FramePts:>0} t&&t.CueId==a.CueId);Check(PreviewAudio.ActiveStreams==0,"manual preview audio survived");});
   await Test("cover applies to preview while underlying LTC keeps moving",async()=>{w.SetCoverVisible(true);await Until(()=>w.Cover.Amount()==1);var size=w.Surface.PixelSize;Check(Center(w.Surface.Readback(),size.Width,size.Height)[0]==255,"preview cover absent");double pts=w.PreviewObservation!.FramePts??0;await Until(()=>w.PreviewObservation!.FramePts>pts+.1);if(Program.Arguments.Contains("--visual-presentation")){w.Topmost=true;w.Title="LTCue — cover verification";await Task.Delay(20000);}});
   await Test("output start retains cover and follows current LTC position",async()=>{await w.ArmAsync();await Until(()=>w.LatestObservation is {FramePts:>0}&&output!=null);await Until(()=>output!.Readback()[0]==0);var d=VideoRenderer.Displays().First(x=>x.Primary!=0);Check(Center(output!.Readback(),d.Width,d.Height)[0]==255,"output cover absent");Check(!w.LatestObservation!.Manual&&w.LatestObservation.FramePts>1,"output restarted from zero");});
   await Test("cue jump under cover and fade return reveal current video",async()=>{Interlocked.Exchange(ref inputFrame,120);await Until(()=>w.LatestObservation is {FramePts:>4});w.SetCoverVisible(false);await Until(()=>w.Cover.Amount()==0);await Task.Delay(80);var d=VideoRenderer.Displays().First(x=>x.Primary!=0);var center=Center(output!.Readback(),d.Width,d.Height);Check(!(center[0]==255&&center[1]==0&&center[2]==0),"old cover retained");});
   await Test("stop external output returns to synchronized preview with cover retained",async()=>{w.SetCoverVisible(true);await Until(()=>w.Cover.Amount()==1);await w.DisarmAsync();await Until(()=>w.PreviewObservation is {FramePts:>0});var size=w.Surface.PixelSize;Check(Center(w.Surface.Readback(),size.Width,size.Height)[0]==255,"cover lost on output stop");Check(!w.IsArmed&&!w.Surface.ProgramMode,"external state retained");});
   await Test("held preview resize preserves cover; manual playback resumes after loss",async()=>{Volatile.Write(ref receiving,0);await Until(()=>w.PreviewObservation?.State==SyncState.LOST);w.Width=700;w.Height=1100;await Task.Delay(350);var size=w.Surface.PixelSize;Check(Center(w.Surface.Readback(),size.Width,size.Height)[0]==255,"resized cover absent");w.SetCoverVisible(false);await Until(()=>w.Cover.Amount()==0);Play(b);await Until(()=>w.Preview.Snapshot.State==PreviewState.Playing);});
   await Test("manual preview hands current position to output without LTC",async()=>{await Until(()=>w.Preview.Snapshot.Position>.2);double position=w.Preview.Snapshot.Position;await w.ArmAsync();await Until(()=>w.LatestObservation is {Manual:true,FramePts:>0} t&&t.CueId==b.CueId);Check(w.LatestObservation!.FramePts>=position-.1,"manual output restarted");});
   await Test("output stop hands manual playback position back to preview",async()=>{var last=w.LatestObservation!;await w.DisarmAsync();await Until(()=>w.Preview.Snapshot.State==PreviewState.Playing);Check(w.Preview.Snapshot.Position>=(last.FramePts??0)-.1,"preview restarted");});
   await Test("clear registered image uses black; persisted fade and image path",async()=>{await w.StopSyncPreviewAsync();w.Cover.Image=null;w.SetCoverVisible(true);await Until(()=>w.Cover.Amount()==1);var size=w.Surface.PixelSize;await Until(()=>Center(w.Surface.Readback(),size.Width,size.Height).Take(3).All(x=>x==0));var saved=InputSettings.Load(Program.Option("--settings"));Check(saved.CoverPath==file&&saved.FadeSeconds==.2,"settings not persisted");});
  }finally{Volatile.Write(ref receiving,0);ProgramPlayback.ProbeObserver=null;await w.DisarmAsync();await w.StopSyncPreviewAsync();await w.Monitor.DisposeAsync();MainWindow.Shutdown(failed?1:0);}
 }
}
